package com.ludo.trailnav.core;
import android.util.Xml;import org.xmlpull.v1.XmlPullParser;import java.io.*;import java.util.*;
public final class GpxParser{private GpxParser(){}
 public static Route parse(InputStream in)throws Exception{XmlPullParser x=Xml.newPullParser();x.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);x.setInput(in,"UTF-8");List<Route.Point> pts=new ArrayList<>();String name=null;boolean inMeta=false,inTrack=false,inPoint=false;double plat=0,plon=0,pele=Double.NaN;int e=x.getEventType();while(e!=XmlPullParser.END_DOCUMENT){if(e==XmlPullParser.START_TAG){String n=x.getName();if("metadata".equals(n))inMeta=true;if("trk".equals(n)||"rte".equals(n))inTrack=true;if(("trkpt".equals(n)||"rtept".equals(n))&&pts.size()<25000){String la=x.getAttributeValue(null,"lat"),lo=x.getAttributeValue(null,"lon");if(la!=null&&lo!=null){plat=Double.parseDouble(la);plon=Double.parseDouble(lo);pele=Double.NaN;inPoint=true;}}else if("ele".equals(n)&&inPoint){String t=x.nextText();try{pele=Double.parseDouble(t.trim());}catch(Exception ignored){pele=Double.NaN;}}else if("name".equals(n)&&name==null&&(inMeta||inTrack)){String t=x.nextText();if(t!=null&&!t.trim().isEmpty())name=t.trim();}}else if(e==XmlPullParser.END_TAG){String n=x.getName();if(("trkpt".equals(n)||"rtept".equals(n))&&inPoint){pts.add(new Route.Point(plat,plon,pele));inPoint=false;}if("metadata".equals(n))inMeta=false;if("trk".equals(n)||"rte".equals(n))inTrack=false;}e=x.next();}if(pts.size()<2)throw new IllegalArgumentException("No usable GPX route points");return new Route(name,pts);}
}
